css:
/* Speaking Coach Dark Style - 口說練習專用暗黑模式 */

/* ============================
   基礎設定
   ============================ */
html, body {
    background-color: #121212;
    color: #e0e0e0;
    margin: 0;
    padding: 0;
}

.card {
    font-family: 'Helvetica Neue', Helvetica, Arial, "Hiragino Kaku Gothic ProN", "Meiryo", sans-serif;
    font-size: 18px;
    line-height: 1.6;
    color: #e0e0e0;
    background-color: #1e1e1e;
    padding: 24px;
    max-width: 650px;
    margin: 16px auto;
    border-radius: 12px;
    border: 1px solid #2c2c2c;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    position: relative;
}

/* ============================
   對方發言區塊 (正面頂部)
   ============================ */
.expression-box {
    background: linear-gradient(135deg, #0d2b45, #121212);
    color: #ffffff;
    padding: 24px 20px;
    border-radius: 8px;
    border-top: 3px solid #ff9f43;
    text-align: center;
    margin-bottom: 24px;
    box-shadow: inset 0 2px 10px rgba(0,0,0,0.4);
}

.topic-tag {
    font-size: 12px;
    font-weight: bold;
    color: #ff9f43;
    text-transform: uppercase;
    letter-spacing: 1px;
    display: block;
    margin-bottom: 16px;
    text-shadow: 0 0 8px rgba(255, 159, 67, 0.3);
}

.prompt-content {
    font-size: 24px;
    font-weight: 700;
    letter-spacing: 0.5px;
    word-break: keep-all;
    line-height: 1.5;
    text-align: left;
    white-space: pre-wrap;
}

/* ============================
   語音頭像圓圈列
   ============================ */
.avatar-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 16px;
    flex-wrap: wrap;
    justify-content: center;
}

.avatar-btn {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    border: 2px solid #444;
    overflow: hidden;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #2a2a2a;
    transition: all 0.25s ease;
    flex-shrink: 0;
    position: relative;
    text-decoration: none;
}

.avatar-btn img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 50%;
}

.avatar-btn:hover {
    border-color: #ff9f43;
    box-shadow: 0 0 10px rgba(255, 159, 67, 0.4);
    transform: scale(1.08);
}

.avatar-btn:active {
    transform: scale(0.95);
}

/* 播放中的圓圈動畫 */
.avatar-btn.playing {
    border-color: #2ecc71;
    box-shadow: 0 0 12px rgba(46, 204, 113, 0.6);
    animation: pulse-ring 1.2s ease-in-out infinite;
}

@keyframes pulse-ring {
    0%   { box-shadow: 0 0 6px rgba(46, 204, 113, 0.4); }
    50%  { box-shadow: 0 0 16px rgba(46, 204, 113, 0.7); }
    100% { box-shadow: 0 0 6px rgba(46, 204, 113, 0.4); }
}

/* 預設播放圖標 (無頭像時) */
.avatar-icon {
    font-size: 18px;
    color: #bdc3c7;
    line-height: 1;
    font-weight: bold;
}

/* Telegram「+」按鈕 */
.tg-add-btn {
    border-color: #3498db;
    background-color: #1a3a5c;
}
.tg-add-btn:hover {
    border-color: #5dade2;
    box-shadow: 0 0 10px rgba(52, 152, 219, 0.5);
}
.tg-add-btn .avatar-icon {
    color: #5dade2;
    font-size: 22px;
}

/* ============================
   通用 Section 區塊
   ============================ */
.divider {
    border: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, #444, transparent);
    margin: 24px 0;
}

.section {
    background-color: #242424;
    border-left: 4px solid #3498db;
    padding: 16px 20px;
    margin-bottom: 16px;
    border-radius: 0 8px 8px 0;
}

.section-title {
    font-size: 13px;
    font-weight: bold;
    color: #95a5a6;
    margin-bottom: 12px;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.section-content {
    font-size: 20px;
    color: #ecf0f1;
    white-space: pre-line;
    font-weight: 500;
    line-height: 1.8;
}

/* 文脈區塊 */
.context-section {
    border-left-color: #9b59b6;
    background: linear-gradient(to right, rgba(155, 89, 182, 0.05), transparent);
}

/* 歷史錄音區塊 */
.recordings-section {
    border-left-color: #e67e22;
    background: linear-gradient(to right, rgba(230, 126, 34, 0.05), transparent);
}

/* 參考範本區塊 */
.references-section {
    border-left-color: #2ecc71;
    background: linear-gradient(to right, rgba(46, 204, 113, 0.05), transparent);
}

.empty-hint {
    font-size: 14px;
    color: #666;
    font-style: italic;
    padding: 8px 0;
}

/* 錄音區「提交新錄音」按鈕 (與折疊狀態的錄音項目統一樣式) */
.rec-submit-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 14px;
    background-color: #2a2a2a;
    color: #bdc3c7;
    border: 1px solid #333;
    border-radius: 6px;
    margin-bottom: 8px;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
    transition: all 0.2s ease;
    user-select: none;
    -webkit-user-select: none;
}
.rec-submit-btn:hover {
    background-color: #333;
    border-color: #e67e22;
    color: #ffffff;
}
.rec-submit-btn:active {
    background-color: #3a3a3a;
}
.rec-submit-icon {
    font-size: 16px;
    line-height: 1;
}
.rec-submit-text {
    font-size: 15px;
}

/* 錄音詳情內的 HTML5 audio 播放器樣式覆寫 */
.rec-audio audio {
    width: 100%;
    height: 36px;
    border-radius: 18px;
    outline: none;
}

/* ============================
   狀態圓點 (共用)
   ============================ */
.status-dot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    margin-right: 8px;
    vertical-align: middle;
    flex-shrink: 0;
}
.dot-red    { background-color: #e74c3c; box-shadow: 0 0 6px rgba(231, 76, 60, 0.5); }
.dot-orange { background-color: #f39c12; box-shadow: 0 0 6px rgba(243, 156, 18, 0.5); }
.dot-green  { background-color: #2ecc71; box-shadow: 0 0 6px rgba(46, 204, 113, 0.5); }

/* ============================
   手風琴 (錄音項目)
   ============================ */
.accordion-item {
    border: 1px solid #333;
    border-radius: 6px;
    margin-bottom: 8px;
    overflow: hidden;
}

.accordion-summary {
    display: flex;
    align-items: center;
    padding: 10px 14px;
    background-color: #2a2a2a;
    cursor: pointer;
    transition: background-color 0.2s ease;
    user-select: none;
    -webkit-user-select: none;
}
.accordion-summary:hover {
    background-color: #333;
}
.accordion-summary:active {
    background-color: #3a3a3a;
}

.accordion-date {
    flex: 1;
    font-size: 15px;
    color: #bdc3c7;
    font-weight: 600;
}

.accordion-score {
    font-size: 14px;
    color: #95a5a6;
    margin-right: 10px;
    font-weight: bold;
}

.accordion-arrow {
    font-size: 14px;
    color: #666;
    transition: transform 0.2s ease;
}

.accordion-detail {
    padding: 14px 16px;
    background-color: #1e1e1e;
    border-top: 1px solid #333;
}

/* 錄音詳情內部元素 */
.rec-audio {
    margin-bottom: 12px;
}

.rec-label {
    font-size: 12px;
    font-weight: bold;
    color: #7f8c8d;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 10px;
    margin-bottom: 4px;
}

.rec-transcript {
    font-size: 17px;
    color: #ecf0f1;
    line-height: 1.7;
    white-space: pre-line;
    padding: 8px 0;
}

.rec-comment {
    font-size: 15px;
    color: #bdc3c7;
    line-height: 1.6;
    white-space: pre-line;
    padding: 8px 0;
    border-left: 3px solid #555;
    padding-left: 12px;
    margin-left: 4px;
}

.rec-score-detail {
    font-size: 16px;
    color: #ecf0f1;
    font-weight: bold;
    padding: 8px 0;
    display: flex;
    align-items: center;
}

/* ============================
   參考範本回覆
   ============================ */
.ref-item {
    border: 1px solid #333;
    border-radius: 6px;
    padding: 12px 14px;
    margin-bottom: 8px;
    background-color: #2a2a2a;
    transition: opacity 0.2s ease;
}

.ref-item.ref-disabled {
    opacity: 0.45;
}

.ref-header {
    display: flex;
    align-items: center;
    margin-bottom: 8px;
}

.ref-date {
    font-size: 14px;
    color: #95a5a6;
    font-weight: 600;
}

.ref-content {
    font-size: 18px;
    color: #ecf0f1;
    line-height: 1.7;
    white-space: pre-line;
}

/* 參考範本內的語音列 */
.ref-item .avatar-row {
    margin-top: 12px;
    justify-content: flex-start;
}

/* ============================
   RWD 手機版調整
   ============================ */
@media screen and (max-width: 480px) {
    .card {
        padding: 12px 8px;
        margin: 0;
        font-size: 16px;
        border: none;
        border-radius: 0;
    }

    .expression-box {
        padding: 16px 12px;
        margin-bottom: 16px;
    }

    .prompt-content {
        font-size: 20px;
    }

    .section {
        padding: 12px 10px;
        margin-bottom: 12px;
        border-left-width: 3px;
        border-radius: 0 4px 4px 0;
    }

    .section-title {
        font-size: 12px;
        margin-bottom: 8px;
    }

    .section-content {
        font-size: 17px;
    }

    .avatar-btn {
        width: 36px;
        height: 36px;
    }

    .avatar-row {
        gap: 8px;
    }

    .accordion-summary {
        padding: 8px 10px;
    }

    .accordion-date {
        font-size: 14px;
    }

    .accordion-detail {
        padding: 10px 12px;
    }

    .rec-transcript {
        font-size: 16px;
    }

    .rec-comment {
        font-size: 14px;
    }

    .ref-content {
        font-size: 16px;
    }
}

/* ============================
   錯誤對比 (紅線標示)
   ============================ */
.error-comparison {
    font-size: 20px;
    line-height: 1.5;
    white-space: pre-wrap;
    color: #bdc3c7;
    margin-bottom: 16px;
}

.error-comparison u {
    color: #e74c3c;
    text-decoration: underline;
    text-decoration-color: #e74c3c;
    text-underline-offset: 4px;
    text-decoration-thickness: 2px;
    font-weight: bold;
}

/* ============================
   對話泡泡 (Context)
   ============================ */
.chat-container {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 8px;
}

.chat-bubble-wrap {
    display: flex;
    width: 100%;
}

.chat-bubble-wrap.chat-left {
    justify-content: flex-start;
}

.chat-bubble-wrap.chat-right {
    justify-content: flex-end;
}

.chat-bubble {
    max-width: 85%;
    padding: 10px 14px;
    border-radius: 12px;
    font-size: 17px;
    line-height: 1.5;
    word-break: break-word;
    white-space: pre-wrap;
    box-shadow: 0 2px 5px rgba(0,0,0,0.2);
}

.chat-left .chat-bubble {
    background-color: #2a2a2a;
    color: #ecf0f1;
    border-bottom-left-radius: 2px;
    border: 1px solid #333;
}

.chat-right .chat-bubble {
    background-color: #1a3a5c;
    color: #ecf0f1;
    border-bottom-right-radius: 2px;
    border: 1px solid #2980b9;
}


/* ============================
   Verb Pair Specific Styles
   ============================ */
.action-btn-row {
    display: flex;
    justify-content: center;
    gap: 15px;
    margin-top: 20px;
}
.action-btn {
    background: #2a2a2a;
    border: 1px solid #444;
    color: #e0e0e0;
    padding: 10px 20px;
    border-radius: 20px;
    cursor: pointer;
    transition: all 0.2s ease;
    font-weight: bold;
}
.action-btn:hover {
    background: #3a3a3a;
    border-color: #3498db;
    color: #fff;
}
.data-row {
    display: flex;
    align-items: center;
    background: #252525;
    padding: 10px;
    margin-bottom: 10px;
    border-radius: 6px;
}
.data-text {
    font-size: 18px;
    line-height: 1.5;
    color: #ecf0f1;
    margin-left: 10px;
}

/* Context Card Specific */
.summary-text {
    font-size: 20px;
    color: #ecf0f1;
    font-weight: 500;
    line-height: 1.8;
    white-space: pre-line;
}
.chat-target-bubble {
    border: 2px solid #2ecc71 !important;
    background-color: #1d3b2b !important;
}

/* Cloze Card Specific */
.translation-content {
    font-size: 16px;
    color: #95a5a6;
    margin-top: 15px;
}
.target-box {
    background-color: #242424;
    padding: 12px;
    border-radius: 8px;
    border-left: 4px solid #2ecc71;
    text-align: left;
    margin-top: 20px;
}
.target-title {
    font-size: 12px;
    color: #2ecc71;
    font-weight: bold;
    margin-bottom: 5px;
}
.target-text {
    font-size: 18px;
    color: #fff;
    font-weight: bold;
}

/* 確保 error-line 的樣式優先度與底線粗細正確 */
.error-line {
    color: #e74c3c !important; 
    text-decoration: underline !important; 
    text-decoration-color: #e74c3c !important;
    text-underline-offset: 4px !important; 
    text-decoration-thickness: 2px !important; 
    font-weight: bold !important;
}
